// lineHead heads a list's second column by what its tab's rows say there.
func lineHead(tab string) string {
	switch tab {
	case "running", "queued":
		return "Progress"
	case "completed":
		return "Import"
	case "pending":
		return "Plan"
	case "failed":
		return "Failure"
	case "skipped":
		return "Reason"
	}
	return "Detail"
}

